import React from 'react';
import { NavLink } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav style={{ display: 'flex', justifyContent: 'space-around', padding: '1rem', background: '#f0f0f0' }}>
      <NavLink to="/" exact activeStyle={{ fontWeight: 'bold', color: 'green' }}>All</NavLink>
      <NavLink to="/full-stack" activeStyle={{ fontWeight: 'bold', color: 'green' }}>Full Stack Development</NavLink>
      <NavLink to="/data-science" activeStyle={{ fontWeight: 'bold', color: 'green' }}>Data Science</NavLink>
      <NavLink to="/cyber-security" activeStyle={{ fontWeight: 'bold', color: 'green' }}>Cyber Security</NavLink>
      <NavLink to="/career" activeStyle={{ fontWeight: 'bold', color: 'green' }}>Career</NavLink>
    </nav>
  );
};

export default Navbar;
